file.content:
                },
            )
        try:
            self.store.save()
        except BaseException:
            for tx in txs:
                self.store.pending.pop(tx.tx_id, None)
            self.store.truncate_audit_events(len(txs))
            return 500, {"error": "persistence failed"}
        items = [{"tx_id": tx.tx_id, "nonce": tx.nonce} for tx in txs]
        return 202, {"items": items, "total": len(items)}

def _sequenced_tx_location(self, tx_id: str) -> str | None:
    """Locate a tx_id across the canonical chain and mempool.

    Returns ``"confirmed"`` when it is in a confirmed block,
    ``"pending"`` when it is in the unconfirmed tip or the mempool, or
    None when nothing holds it. Caller must hold the store lock.
    """
    for block in self.store.chain:
        if any(tx.tx_id == tx_id for tx in block.transactions):
            return (
                STATUS_CONFIRMED
                if block.status == STATUS_CONFIRMED
                else STATUS_PENDING
            )
    if tx_id in self.store.pending:
        return STATUS_PENDING
    return None

def get_account_sequence(self, account: object) -> tuple[int, dict]:
    """GET /v1/accounts/{account}/sequence — the account's nonce stream.

    Returns ``{account, next_sequence, pending_sequences,
    confirmed_sequences}``; the two arrays list ``{nonce, tx_id}`` pairs
    ascending by nonce. An account that has never sent a sequenced
    transfer (a "stranger") still answers 200 with next_sequence 0 and
    empty arrays. A non-string or empty account is 400 input.
    """
    if not isinstance(account, str) or not account:
        return 400, {"error": "input"}
    with self.store.lock:
        state = self.store.sequences.get(account)
        if state is None:
            return 200, {
                "account": account,
                "next_sequence": 0,
                "pending_sequences": [],
                "confirmed_sequences": [],
            }
        confirmed = [
            {"nonce": nonce, "tx_id": state["confirmed"][nonce]}
            for nonce in sorted(state["confirmed"])
        ]
        reserved = [
            {"nonce": nonce, "tx_id": state["pending"][nonce]}
            for nonce in sorted(state["pending"])
        ]
        return 200, {
            "account": account,
            "next_sequence": self.store.sequence_next(state),
            "pending_sequences": reserved,
            "confirmed_sequences": confirmed,
        }

def get_transaction(self, tx_id: object) -> tuple[int, dict]:
    """GET /v1/transactions/{tx_id} — one transaction receipt.

    The lookup covers the canonical chain and the mempool only; candidate
    forks are never exposed. A ``tx_id`` that is not exactly 64 lowercase
    hex characters, or one nothing holds, returns 404.

    A mempool transaction is reported ``pending`` with ``height``,
    ``block_hash`` and ``index`` all null. A transaction packed into the
    unconfirmed tip block is ``pending`` too, anchored at that block with
    its 0-based in-block index. A transaction in a confirmed block is
    ``confirmed``. Every receipt is built from the stored signed
    transaction: the id is recomputed from its canonical message (never
    taken from an index or a fork-side cache) and the fields are strictly
    re-typed (non-empty strings, a positive non-boolean integer amount),
    so adoption, rollback and restart can only ever surface the current
    canonical/pending state.
    """
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction not found"}
    with self.store.lock:
        # Canonical chain first: confirmed blocks, then at most one
        # pending tip. The stored signed transaction is the sole source
        # for the receipt, and its id is recomputed rather than trusted
        # from any lookup key.
        for block in self.store.chain:
            for index, tx in enumerate(block.transactions):
                if tx.tx_id != tx_id:
                    continue
                if not self._is_receipt_tx_well_typed(tx):
                    return 404, {"error": "transaction not found"}
                status = (
                    STATUS_CONFIRMED
                    if block.status == STATUS_CONFIRMED
                    else STATUS_PENDING
                )
                return 200, self._transaction_receipt(
                    tx, status, block.height, block.block_hash, index
                )
        # Still unpacked in the mempool.
        tx = self.store.pending.get(tx_id)
        if tx is not None:
            if not self._is_receipt_tx_well_typed(tx):
                return 404, {"error": "transaction not found"}
            return 200, self._transaction_receipt(
                tx, STATUS_PENDING, None, None, None
            )
        return 404, {"error": "transaction not found"}

@staticmethod
def _is_receipt_tx_well_typed(tx: Transaction) -> bool:
    """Strict receipt-time type check of a stored signed transaction.

    Every stored transaction already passed these checks at submission
    (and again during snapshot recovery); the re-check guarantees a
    receipt can never serialize a value that violates the response
    contract, even if an in-memory invariant were broken.
    """
    return (
        isinstance(tx.sender, str)
        and bool(tx.sender)
        and isinstance(tx.recipient, str)
        and bool(tx.recipient)
        and isinstance(tx.amount, int)
        and not isinstance(tx.amount, bool)
        and tx.amount > 0
        and isinstance(tx.signature, str)
        and bool(tx.signature)
        and (
            tx.nonce is None
            or (isinstance(tx.nonce, int) and not isinstance(tx.nonce, bool) and tx.nonce >= 0)
        )
    )

@staticmethod
def _transaction_receipt(
    tx: Transaction,
    status: str,
    height: int | None,
    block_hash: str | None,
    index: int | None,
) -> dict:
    """The fixed nine-field receipt shape for legacy transfers.

    A sequenced transfer appends one further field, ``nonce`` (its
    non-negative sequence number), after ``index``; a legacy transfer
    keeps the exact nine-field document unchanged.
    """
    receipt = {
        "tx_id": tx.tx_id,
        "from": tx.sender,
        "to": tx.recipient,
        "amount": tx.amount,
        "signature": tx.signature,
        "status": status,
        "height": height,
        "block_hash": block_hash,
        "index": index,
    }
    if tx.nonce is not None:
        receipt["nonce"] = tx.nonce
    return receipt

def get_finalized_receipt(self, tx_id: object) -> tuple[int, dict]:
    """GET /v1/transactions/{tx_id}/finalized-receipt — an offline-verifiable
    finalized transaction receipt.

    Lookup and typing rules mirror :meth:`get_transaction`: a ``tx_id``
    that is not exactly 64 lowercase hex characters, or one nothing
    holds on the canonical chain (the mempool and candidate forks are
    not matches here), returns 404. A transaction still in the mempool
    or packed into the unconfirmed pending tip is not final and returns
    409.

    On success the whole document is snapshotted under one store lock
    together with the current audit signer, so the receipt, proof,
    headers and finality credential can never mix chain states. The
    body has the fixed key order ``receipt, proof, headers, finality``:
    ``receipt`` is the fixed nine-field receipt with ``status``
    confirmed; ``proof`` is the single-transaction Merkle proof of
    ``GET /v1/blocks/{height}/proof/{tx_id}``; ``headers`` run from the
    transaction's own confirmed block up to and including the highest
    confirmed block in ascending height, each item in the signed header
    page's five-field shape (every item confirmed); and ``finality`` is
    exactly the ``GET /v1/chain/finality`` document, whose
    ``finalized`` names that last header.
    """
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction not found"}
    from . import light_client

    with self.store.lock:
        matched: tuple[Block, int, Transaction] | None = None
        for block in self.store.chain:
            for index, tx in enumerate(block.transactions):
                if tx.tx_id == tx_id:
                    matched = (block, index, tx)
                    break
            if matched is not None:
                break
        if matched is None:
            # Neither the canonical chain nor (below) the mempool holds
            # the id; candidate forks are never exposed.
            if tx_id in self.store.pending:
                return 409, {"error": "transaction is not confirmed"}
            return 404, {"error": "transaction not found"}
        block, index, tx = matched
        if not self._is_receipt_tx_well_typed(tx):
            return 404, {"error": "transaction not found"}
        if block.status != STATUS_CONFIRMED:
            # A packed-but-unconfirmed transaction can only sit in the
            # pending chain tip.
            return 409, {"error": "transaction is not confirmed"}

        tx_ids = [candidate.tx_id for candidate in block.transactions]
        proof = {
            "height": block.height,
            "tx_id": tx.tx_id,
            "index": index,
            "merkle_root": block.merkle_root,
            "block_hash": block.block_hash,
            "siblings": crypto.merkle_proof(tx_ids, index),
        }

        finalized_block = next(
            candidate
            for candidate in reversed(self.store.chain)
            if candidate.status == STATUS_CONFIRMED
        )
        # Every block from the transaction's block through the highest
        # confirmed block is confirmed: the only pending block the chain
        # ever carries is its tip, which the slice stops before.
        headers = [
            self._header_entry(candidate)
            for candidate in self.store.chain[
                block.height : finalized_block.height + 1
            ]
        ]
        finalized = self._anchor_descriptor(finalized_block)
        tip = self._fork_summary(self.store.chain)
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot (including migrated legacy ones) carries a
            # current audit signer after recovery; reaching here is a
            # programming error rather than a client-visible condition.
            raise RuntimeError(
                "no audit signer available for finalized receipt"
            )
        auth = light_client.sign_finality(
            signer["private_key"], signer["version"], finalized, tip
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        finality = {
            "finalized": finalized,
            "tip": tip,
            "auth": auth,
        }
        return 200, {
            "receipt": self._transaction_receipt(
                tx, STATUS_CONFIRMED, block.height, block.block_hash, index
            ),
            "proof": proof,
            "headers": headers,
            "finality": finality,
        }

def get_finalized_receipts(self, payload: object) -> tuple[int, dict]:
    """POST /v1/transactions/finalized-receipts — a batch of
    offline-verifiable finalized receipts sharing one chain snapshot.

    The body must be a JSON object containing exactly the ``tx_ids``
    key: a non-empty list of distinct 64-lowercase-hex strings (the
    same rules as ``POST /v1/blocks/{height}/proofs``). A malformed
    body — parse failure, missing/extra keys, a wrong type, an empty
    list, duplicates or a wrongly formatted id — is 400 and never
    touches state. If every id is well formed but any of them is held
    neither on the canonical chain nor in the mempool (candidate forks
    are never matches), the answer is 404; otherwise, when nothing is
    missing but at least one transaction is still in the mempool or
    packed into the unconfirmed pending tip, the answer is 409.

    On success the chain and the current audit signer are snapshotted
    together under one store lock (exactly as for
    :meth:`get_finalized_receipt`), so every item, the shared header
    run and the finality credential can never mix chain states. The
    body has the fixed key order ``items, headers, finality``:
    ``items`` is ordered by ``tx_id`` ascending regardless of the
    request order, and each item has the fixed key order
    ``receipt, proof`` using the exact single-receipt contract;
    ``headers`` is the continuous five-field confirmed header run from
    the **lowest** transaction's block up to and including the highest
    confirmed block (every item confirmed); ``finality`` is exactly the
    ``GET /v1/chain/finality`` document, whose ``finalized`` names the
    last header.
    """
    if not isinstance(payload, dict) or set(payload) != {"tx_ids"}:
        return 400, {"error": "request body must be a JSON object with only 'tx_ids'"}
    tx_ids_raw = payload["tx_ids"]
    if not isinstance(tx_ids_raw, list) or not tx_ids_raw:
        return 400, {"error": "field 'tx_ids' must be a non-empty array"}
    if any(not crypto.is_hex64(tx_id) for tx_id in tx_ids_raw):
        return 400, {
            "error": "every tx_id must be a string of 64 lowercase hex characters"
        }
    if len(set(tx_ids_raw)) != len(tx_ids_raw):
        return 400, {"error": "tx_ids must be distinct"}

    from . import light_client

    with self.store.lock:
        requested = sorted(tx_ids_raw)
        requested_set = set(requested)
        # One pass over the canonical chain (which includes the pending
        # tip) locates every request id at its first inclusion point.
        located: dict[str, tuple[Block, int, Transaction]] = {}
        for block in self.store.chain:
            for index, tx in enumerate(block.transactions):
                if tx.tx_id in requested_set and tx.tx_id not in located:
                    located[tx.tx_id] = (block, index, tx)
        # A 404 takes precedence over a 409: an id absent from both the
        # chain and the mempool does not exist, even if another id of
        # the same batch is merely unconfirmed.
        unknown = [
            tx_id
            for tx_id in requested
            if tx_id not in located
            and tx_id not in self.store.pending
        ]
        if unknown:
            return 404, {"error": "transaction not found"}
        for tx_id, (_block, _index, tx) in located.items():
            if not self._is_receipt_tx_well_typed(tx):
                return 404, {"error": "transaction not found"}
        if any(
            tx_id in self.store.pending
            or located[tx_id][0].status != STATUS_CONFIRMED
            for tx_id in requested
        ):
            # Packed-but-unconfirmed transactions can only sit in the
            # pending chain tip; everything else here is in the mempool.
            return 409, {"error": "transaction is not confirmed"}

        items = []
        lowest_height: int | None = None
        for tx_id in requested:
            block, index, tx = located[tx_id]
            if lowest_height is None or block.height < lowest_height:
                lowest_height = block.height
            items.append(
                {
                    "receipt": self._transaction_receipt(
                        tx,
                        STATUS_CONFIRMED,
                        block.height,
                        block.block_hash,
                        index,
                    ),
                    "proof": {
                        "height": block.height,
                        "tx_id": tx.tx_id,
                        "index": index,
                        "merkle_root": block.merkle_root,
                        "block_hash": block.block_hash,
                        "siblings": crypto.merkle_proof(
                            [candidate.tx_id for candidate in block.transactions],
                            index,
                        ),
                    },
                }
            )

        finalized_block = next(
            candidate
            for candidate in reversed(self.store.chain)
            if candidate.status == STATUS_CONFIRMED
        )
        # The run spans the lowest transaction block through the highest
        # confirmed block; every block in between is confirmed because
        # the only pending block the chain ever carries is its tip.
        assert lowest_height is not None
        headers = [
            self._header_entry(candidate)
            for candidate in self.store.chain[
                lowest_height : finalized_block.height + 1
            ]
        ]
        finalized = self._anchor_descriptor(finalized_block)
        tip = self._fork_summary(self.store.chain)
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot (including migrated legacy ones) carries a
            # current audit signer after recovery; reaching here is a
            # programming error rather than a client-visible condition.
            raise RuntimeError(
                "no audit signer available for finalized receipts"
            )
        auth = light_client.sign_finality(
            signer["private_key"], signer["version"], finalized, tip
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        return 200, {
            "items": items,
            "headers": headers,
            "finality": {
                "finalized": finalized,
                "tip": tip,
                "auth": auth,
            },
        }

def audit_receipt_proofs(self, payload: object) -> tuple[int, dict]:
    """POST /v1/transactions/receipt-proofs/audit — offline audit summary
    for a batch of ``receipt_proof`` documents.

"""Command line interface: send, send-sequenced, send-sequenced-batch, sequence, tx, mine, block, account, proof, proofs,
state-root,
state-proof, state-proofs, confirm, rollback, status, candidates, chain, adopt, export,
index, sync, sync-range, sync-attested, sync-range-attested, syncs,
sync-history, sync-export, sync-range-export, chain-range,
sync-state-audit, sync-plan,
audit, audit-export, trust
(add/rotate/revoke/export/allowlist-add/allowlist-remove) and offline
verify/audit-verify/consistency and offline verify-range/verify-range-batch
subcommands, the receipt-proofs-audit batch audit subcommand, plus the
offline checkpoint-history history-trust,
history-export and header-locators subcommands.

The CLI talks to a running ledger server over HTTP and prints each response as
a single line of JSON with exactly the same field names as the HTTP API.

Signing a transaction locally is supported through ``send --signing-key``;
the key may be 32 raw hex bytes or ``@/path/to/ed25519-key.pem``. An already
produced signature can be passed instead with ``--from/--signature``. The
``candidates`` subcommand takes the candidate fork's block array (or a
``{"blocks": [...]}`` object) as a single JSON argument.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request
from typing import Any

from . import crypto

DEFAULT_BASE_URL = os.environ.get("LEDGER_BASE_URL", "http://127.0.0.1:8080")


# -- HTTP helpers ------------------------------------------------------------


def _request(
    method: str, url: str, payload: dict | None, sort_keys: bool = True
) -> tuple[int, dict]:
    data = None
    headers = {"Accept": "application/json"}
    if payload is not None:
        data = json.dumps(payload, sort_keys=sort_keys).encode("utf-8")
        headers["Content-Type"] = "application/json"
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(request) as response:
            return response.status, json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        try:
            body = json.loads(exc.read().decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            body = {"error": exc.reason}
        return exc.code, body
    except (urllib.error.URLError, OSError) as exc:
        return 0, {"error": f"cannot reach ledger server: {exc}"}


def _emit(status: int, body: dict, sort_keys: bool = True) -> int:
    print(json.dumps(body, sort_keys=sort_keys, ensure_ascii=False))
    # 2xx responses are success; anything else (incl. connection failure) is 1.
    return 0 if 200 <= status < 300 else 1


# -- signing key handling ----------------------------------------------------


def _load_signing_key(spec: str):
    """Load an Ed25519 private key from raw hex or an ``@file`` (hex or PEM)."""
    from cryptography.hazmat.primitives import serialization

    if spec.startswith("@"):
        with open(spec[1:], "rb") as fh:
            material = fh.read()
    else:
        material = spec.encode("ascii")
    stripped = material.strip()
    if stripped.startswith(b"-----BEGIN"):
        key = serialization.load_pem_private_key(stripped, password=None)
    else:
        raw = bytes.fromhex(stripped.decode("ascii"))
        if len(raw) != 32:
            raise ValueError("signing key must be 32 raw bytes (64 hex chars)")
        from cryptography.hazmat.primitives.asymmetric.ed25519 import (
            Ed25519PrivateKey,
        )

        key = Ed25519PrivateKey.from_private_bytes(raw)
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

    if not isinstance(key, Ed25519PrivateKey):
        raise ValueError("signing key is not an Ed25519 private key")
    return key


def _public_key_hex(key) -> str:
    from cryptography.hazmat.primitives import serialization

    return key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


# -- subcommands -------------------------------------------------------------


def cmd_send(args: argparse.Namespace) -> int:
    if args.signing_key:
        try:
            key = _load_signing_key(args.signing_key)
        except (ValueError, OSError, TypeError) as exc:
            return _emit(400, {"error": f"invalid signing key: {exc}"})
        sender = _public_key_hex(key)
        message = crypto.canonical_message(sender, args.to, args.amount)
        signature = key.sign(message).hex()
    else:
        if not args.sender or not args.signature:
            return _emit(
                400,
                {"error": "provide either --signing-key or both --from and --signature"},
            )
        sender, signature = args.sender, args.signature

    payload = {
        "from": sender,
        "to": args.to,
        "amount": args.amount,
        "signature": signature,
    }
    status, body = _request("POST", f"{args.base_url}/v1/transactions", payload)
    return _emit(status, body)


